    public BigDecimal ajustarFrete(BigDecimal frete) {
        return frete;
    }

    public boolean temBrinde(BigDecimal subtotal) {
        return false;
    }

    public BigDecimal credito(BigDecimal subtotal) {
        return Dinheiro.percentual(subtotal, taxaCredito);
    }
}

