18	@Service
19	public class CalculadoraResumo {
20	
21	    public ResumoCompra calcular(PedidoRequest request) {
22	        Pedido pedido = new Pedido(request.itens());
23	        NivelClube nivel = buscar(NivelClube.class, request.nivelClube(), Erro.NIVEL_CLUBE_INVALIDO);
24	        Regiao regiao = buscar(Regiao.class, request.regiao(), Erro.REGIAO_INVALIDA);
25	        ModalidadeEntrega modalidade = buscar(ModalidadeEntrega.class, request.modalidadeEntrega(), Erro.MODALIDADE_INVALIDA);
26	        modalidade.validarPara(pedido);
27	
28	        Optional<Cupom> cupom = Optional.ofNullable(request.cupom())
29	                .filter(codigo -> !codigo.isBlank())
30	                .map(codigo -> buscar(Cupom.class, codigo, Erro.CUPOM_INVALIDO));
31	        cupom.ifPresent(c -> c.validarPara(pedido));
32	
33	        FormaPagamento forma = buscar(FormaPagamento.class, request.formaPagamento(), Erro.FORMA_PAGAMENTO_INVALIDA);
34	        int parcelas = request.parcelas() == null ? 1 : request.parcelas();
35	        forma.validarParcelas(parcelas);
36	
37	        BigDecimal subtotal = pedido.subtotal();
38	        BigDecimal frete = nivel.ajustarFrete(modalidade.frete(pedido));
39	        BigDecimal desconto = cupom.map(c -> c.desconto(pedido, frete)).orElse(Dinheiro.ZERO);
40	        BigDecimal seguro = regiao.seguro(subtotal);
41	        BigDecimal total = subtotal.subtract(desconto).add(frete).add(seguro);
42	
43	        forma.validarDisponibilidade(total);
44	        Pagamento pagamento = forma.aplicar(total, parcelas);
45	
46	        return new ResumoCompra(
47	                subtotal,
48	                desconto,
49	                frete,
50	                modalidade.prazoDias(),
51	                seguro,
52	                pagamento.totalFinal().subtract(total),
53	                pagamento.totalFinal(),
54	                pagamento.parcelas(),
55	                pagamento.valorParcela(),
56	                nivel.credito(subtotal),
57	                nivel.temBrinde(subtotal));
58	    }
59	
60	    private static <E extends Enum<E>> E buscar(Class<E> tipo, String nome, Erro erro) {
61	        return Busca.porNome(tipo, nome).orElseThrow(() -> new RecusaPedido(erro));
62	    }
63	}
