3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	import java.math.RoundingMode;
6	
7	public enum FormaPagamento {
8	
9	    PIX {
10	        @Override
11	        public Pagamento aplicar(BigDecimal total, int parcelas) {
12	            return Pagamento.avista(total.subtract(Dinheiro.percentual(total, DESCONTO_PIX)));
13	        }
14	    },
15	
16	    BOLETO {
17	        @Override
18	        public void validarDisponibilidade(BigDecimal total) {
19	            if (total.compareTo(LIMITE_BOLETO) > 0) {
20	                throw new RecusaPedido(Erro.FORMA_PAGAMENTO_INDISPONIVEL);
21	            }
22	        }
23	
24	        @Override
25	        public Pagamento aplicar(BigDecimal total, int parcelas) {
26	            return Pagamento.avista(total.add(TARIFA_BOLETO));
27	        }
28	    },
29	
30	    CARTAO {
31	        @Override
32	        public void validarParcelas(int parcelas) {
33	            if (parcelas < 1 || parcelas > MAX_PARCELAS_CARTAO) {
34	                throw new RecusaPedido(Erro.PARCELAMENTO_INVALIDO);
35	            }
36	        }
37	
38	        @Override
39	        public Pagamento aplicar(BigDecimal total, int parcelas) {
40	            if (parcelas <= PARCELAS_SEM_JUROS) {
41	                BigDecimal parcela = total.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
42	                return new Pagamento(total, parcela, parcelas);
43	            }
44	            BigDecimal fator = BigDecimal.ONE.add(TAXA_JUROS_CARTAO).pow(parcelas);
45	            BigDecimal parcela = Dinheiro.centavos(total.multiply(TAXA_JUROS_CARTAO).multiply(fator)
46	                    .divide(fator.subtract(BigDecimal.ONE), MathContext.DECIMAL128));
47	            return new Pagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela, parcelas);
48	        }
49	    };
50	
51	    private static final BigDecimal DESCONTO_PIX = new BigDecimal("0.05");
52	    private static final BigDecimal TARIFA_BOLETO = new BigDecimal("3.49");
53	    private static final BigDecimal LIMITE_BOLETO = new BigDecimal("1000");
54	    private static final BigDecimal TAXA_JUROS_CARTAO = new BigDecimal("0.0199");
55	    private static final int PARCELAS_SEM_JUROS = 3;
56	    private static final int MAX_PARCELAS_CARTAO = 12;
57	
58	    public void validarParcelas(int parcelas) {
59	        if (parcelas != 1) {
60	            throw new RecusaPedido(Erro.PARCELAMENTO_INVALIDO);
61	        }
62	    }
63	
64	    public void validarDisponibilidade(BigDecimal total) {
65	    }
66	
67	    public abstract Pagamento aplicar(BigDecimal total, int parcelas);
68	}
